{
  "type": "object",
  "properties": {
    "verdict": { "type": "string", "enum": ["APPROVED", "CHANGES_REQUIRED"] },
    "summary": { "type": "string" },
    "findings": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "severity": { "type": "string", "enum": ["P0", "P1", "P2"] },
          "title": { "type": "string" },
          "evidence": { "type": "string" },
          "impact": { "type": "string" },
          "required_action": { "type": "string" }
        },
        "required": ["severity", "title", "evidence", "impact", "required_action"],
        "additionalProperties": false
      }
    },
    "red_causal": { "type": "boolean" },
    "green_closes_red": { "type": "boolean" },
    "scope_preserved": { "type": "boolean" },
    "retained_behavior_preserved": { "type": "boolean" },
    "evidence_sufficient": { "type": "boolean" },
    "f5a_closable": { "type": "boolean" }
  },
  "required": [
    "verdict",
    "summary",
    "findings",
    "red_causal",
    "green_closes_red",
    "scope_preserved",
    "retained_behavior_preserved",
    "evidence_sufficient",
    "f5a_closable"
  ],
  "additionalProperties": false
}

