101	// Read the declaration actually produced by seal/adoption, exactly as the
102	// retained D.108 successor room fixture does. Never synthesize epoch authority.
103	async function snapshotDeclaration(databaseName: string) {
104		const database = await request(indexedDB.open(`${databaseName}--drp-snapshot-quarantine-v1`));
105		try {
106			const transaction = database.transaction(["chunks", "scopes"], "readonly");
107			const [scopes, chunks] = await Promise.all([
108				request(transaction.objectStore("scopes").getAll()) as Promise<Record<string, unknown>[]>,
109				request(transaction.objectStore("chunks").getAll()) as Promise<Record<string, unknown>[]>,
110			]);
111			// The close snapshots predecessor epoch 0; its verified payload is the
112			// authenticated application base imported by the epoch-1 successor.
113			const verified = scopes.filter((scope) => scope.state === "verified" && scope.epoch === 0);
114			if (verified.length !== 1) throw new TypeError("D110C_0C1F5B0U_REPLAY_SNAPSHOT_AMBIGUOUS");
115			const scope = required(verified[0]);
116			const selected = chunks
117				.filter((row) => ["objectId", "epoch", "anchor", "manifestDigest"].every((key) => row[key] === scope[key]))
118				.sort((left, right) => Number(left.index) - Number(right.index));
119			if (selected.length !== scope.chunkCount) throw new TypeError("D110C_0C1F5B0U_REPLAY_SNAPSHOT_INCOMPLETE");
120			return {
121				chunks: selected.map((row) => ({ byteLength: row.byteLength, digest: row.digest, index: row.index })),
122				exactCanonicalManifestBytes: new Uint8Array(scope.exactCanonicalManifestBytes as Uint8Array),
123				scope: {
124					anchor: scope.anchor,
125					epoch: scope.epoch,
126					manifestDigest: scope.manifestDigest,
127					objectId: scope.objectId,
128				},
129				totalBytes: scope.totalBytes,
130			} as NonNullable<CreateV3RoomSessionInput["successorSnapshotDeclaration"]>;
131		} finally {
132			database.close();
133		}
134	}
