136	async function genuineSuccessor() {
137		const identity = ++ordinal;
138		const databaseName = `d110c-f5b0u-successor-replay-${identity}`;
139		const objectId = `creator:${identity.toString(16).padStart(32, "0")}`;
140		const base = createV3ChatApplication("alice");
141		const migration = required(base.migration);
142		const application = {
143			...base,
144			migration: {
145				...migration,
146				canonicalStateBytes: (...args: Parameters<typeof migration.canonicalStateBytes>) => {
147					const bytes = migration.canonicalStateBytes(...args);
148					if (observed.phase === "reopen") observed.events.push("validated-application-state");
149					return bytes;
150				},
151			},
