153		const signers = [{ publicKey: author, signerId: "creator" }];
154		const creatorInvite = await createV3RoomCreatorInviteMaterial({
155			blueprintDigest: required(base.catalog.blueprintDigests[0]),
156			exactCanonicalApplicationStateBytes: encodeCanonical([]),
157			exactCanonicalLatchedAclBytes: encodeCanonical({
158				epoch: 0,
159				kind: "drp-v3-latched-acl",
160				members: [{ author, finalityKey: author, groups: ["admin", "finality", "writer"] }],
161				objectId,
162				permissionless: false,
163				version: 1,
164			}),
165			exactCanonicalParametersCarrierBytes: encodeCanonical({
166				maxDependencies: 16,
167				maxEpochBytes: 8_388_608,
168				maxEpochVertices: 8192,
169				maxPendingBytes: 16_777_216,
170				maxPendingEntries: 4096,
171				maxSnapshotBytes: 268_435_456,
172				snapshotChunkBytes: 131_072,
173			}),
174			exactCanonicalProfileBytes: encodeCanonical({
175				cryptoSuiteId: "ed25519-sha256-v3",
176				profileId: "creator-trusted-v1",
177				quorum: 1,
178				signers,
179			}),
180			exactCanonicalSignerSetBytes: encodeCanonical(signers),
181			objectId,
182			signGenesisAnchorDigest: (digest) => Promise.resolve(ed25519.sign(digest, seed)),
183		});
184		let state: V3RoomHeadState | null = null;
185		const success = () => ({ ok: true as const, state: structuredClone(state) });
186		const roomHeadAuthority: CreateV3RoomSessionInput["roomHeadAuthority"] = {
187			initialization: { kind: "create" },
188			read: () => Promise.resolve(success()),
189			create: async (input) => {
190				await Promise.resolve();
191				if (state === null) state = { pending: null, stable: input.stable };
192				return success();
193			},
194			migrate: () => Promise.resolve({ ok: false, reason: "conflict" }),
195			begin: async (input) => {
196				await Promise.resolve();
197				if (!Buffer.from(encodeCanonical(input.expected)).equals(Buffer.from(encodeCanonical(state))))
198					return { ok: false, reason: "conflict" };
199				const previous = required(state).stable;
200				state = { stable: previous, pending: { previous, next: input.next } };
201				return success();
202			},
203			commit: async (input) => {
204				await Promise.resolve();
205				if (!Buffer.from(encodeCanonical(input.expected)).equals(Buffer.from(encodeCanonical(state))))
206					return { ok: false, reason: "conflict" };
207				state = { pending: null, stable: required(required(state).pending).next };
208				return success();
209			},
210		};
211		const finality = await createRecoverableFinalitySigner({ seed });
212		const accepted: string[] = [];
213		const input: CreateV3RoomSessionInput = {
214			application,
215			author,
216			creatorInvite,
217			databaseName,
218			initialLogicalTime: 3,
219			issuanceDatabaseName: databaseName,
220			objectId,
221			onAcceptedVertex: (vertex) => {
222				if (observed.phase !== "reopen") return;
223				observed.events.push(`commit:${vertex.authorSequence}`);
224				if (observed.fault === "commit") throw new Error("D110C_0C1F5B0U_REPLAY_COMMIT_FAILED");
225				if (observed.fault === "second-commit" && accepted.length === 1) {
226					observed.fault = "none";
