236				},
237				openEphemeral: () => {
238					throw new Error("not used");
239				},
240				requestRetainedHistory: () => undefined,
241				setIngressHandler: () => undefined,
242				setRetainedPublisher: () => undefined,
243			}),
244			publicKeyBytes: publicKey,
245			roomHeadAuthority,
246			signRegisteredVertexDigest: (digest) => Promise.resolve(ed25519.sign(digest, seed)),
247		};
248		const room = await createV3RoomSession({ ...input, creatorFinalitySigner: finality.signer });
249		sessions.push(room);
250		await room.issue({ action: "message", clientOperationId: "snapshot", text: "snapshot" });
251		const sealed = await room.sealEpoch();
252		if (sealed.ok !== true) throw new TypeError(`D110C_0C1F5B0U_REPLAY_CLOSE_FAILED:${JSON.stringify(sealed)}`);
253		await room.adoptCreatorSuccessor();
254		if (room.authority()?.epoch !== 1) throw new TypeError("D110C_0C1F5B0U_REPLAY_ADOPTION_FAILED");
255		observed.deliveries = [];
256		for (const clientOperationId of ["above-snapshot-1", "above-snapshot-2"])
257			await room.issue({ action: "message", clientOperationId, text: clientOperationId });
258		const expected = structuredClone(observed.deliveries);
259		if (expected.length !== 2) throw new TypeError("D110C_0C1F5B0U_REPLAY_ISSUED_EVIDENCE_INCOMPLETE");
260		const projection = room.projection();
261		const authority = room.authority();
262		const declaration = await snapshotDeclaration(databaseName);
263		await room.close();
264		sessions.splice(sessions.indexOf(room), 1);
265		observed.phase = "reopen";
266		observed.deliveries = [];
267		observed.events = [];
268		observed.transportCloses = 0;
269		const reopen = async () => {
270			const reopened = await createV3RoomSession({
271				...input,
272				roomHeadAuthority: { ...roomHeadAuthority, initialization: { kind: "reopen" } },
273				successorSnapshotDeclaration: declaration,
274			});
275			sessions.push(reopened);
276			return reopened;
277		};
278		const readIssuance = async () => {
279			const store = await createBrowserDurableIssuanceStore({ primaryDatabaseName: databaseName });
280			try {
