282				const lineage = await store.readLineage(scope);
283				if (lineage.next > 16) throw new TypeError("D110C_0C1F5B0V_UNEXPECTED_ISSUANCE_GROWTH");
284				const rows = await Promise.all(
285					Array.from({ length: lineage.next + 1 }, (_, sequence) => store.readIssued(scope, sequence))
286				);
287				return { lineage, rows };
288			} finally {
289				await store.close();
290			}
291		};
292		return { accepted, authority, expected, projection, readIssuance, reopen };
293	}
