407				if (attempted[0]?.status === "fulfilled") {
408					const projection = target.projection() as unknown as { accepted: { clientOperationId: string }[] };
409					expect(projection.accepted.map((row) => row.clientOperationId).sort()).toEqual([
410						"after",
411						"message-0",
412						"message-1",
413					]);
414				}
415			}
416		);
417		it("queues migration rehearsal behind startup recovery without a nested lifetime-tail deadlock", async () => {
418			observation.fault = "legacy-unknown";
419			const admissionErrors: unknown[] = [];
420			observation.onAdmissionError = (error) => admissionErrors.push(error);
421			let release!: () => void;
422			observation.faultGate = new Promise<void>((resolve) => {
423				release = resolve;
424			});
425			const reached = new Promise<void>((resolve) => {
426				observation.onFault = resolve;
427			});
428			const { target, rehearsal } = await openRebasePair(2, 100, false, true);
429			const issued = target.issue({ action: "message", clientOperationId: "after", text: "continued" });
430			await Promise.race([
431				reached,
432				issued.then(() => {
433					throw new Error("D110C_0C1F5B0U_MIGRATION_FAULT_NOT_REACHED");
434				}),
435			]);
436			const migration = target.rehearseMigration(rehearsal);
437			const activation = migration.then((receipt) =>
438				target.activateMigration({
439					targetCreatorInvite: rehearsal.targetCreatorInvite,
440					exactCanonicalRecordBytes: receipt.exactCanonicalRecordBytes,
441					recordVertexDigest: receipt.recordVertexDigest,
442				})
443			);
444			const observedActivation = activation.then(
445				() => ({ status: "fulfilled" as const }),
446				(error: unknown) => ({
447					status: "rejected" as const,
448					message: error instanceof Error ? error.message : String(error),
449				})
450			);
451			release();
452			const results = await Promise.allSettled([issued, migration]);
453			expect.soft(results[0]?.status, "D110C_0C1F5B0U_QUEUED_ISSUE_NOT_RECOVERED").toBe("fulfilled");
454			expect.soft(results[1]?.status, "D110C_0C1F5B0U_MIGRATION_DID_NOT_RESUME").toBe("fulfilled");
455			expect.soft(await observedActivation, "D110C_0C1F5B0U_MIGRATION_ACTIVATION_BOUNDARY_DIFFERS").toEqual({
456				status: "rejected",
457				message: "v3 room migration activation failed: terminal-rejected",
458			});
459			expect
460				.soft(
461					admissionErrors.map((error) => (error instanceof Error ? error.message : String(error))),
462					"D110C_0C1F5B0U_MIGRATION_FRONTIER_CAUSE_DIFFERS"
463				)
464				.toEqual(["v3 room rebase outbox failed: record-rejected"]);
465			expect(
466				observation.activate.filter((plane) => plane.currentEphemeralAuthority() !== undefined).length
467			).toBeLessThanOrEqual(1);
468			await target.close();
469			expect(observation.activate.filter((plane) => plane.currentEphemeralAuthority() !== undefined)).toHaveLength(0);
470		});
471		it("keeps a store-close cleanup failure terminal after signed recovery", async () => {
472			observation.fault = "partial-unknown";
473			const { target } = await openRebasePair(2, 33_000);
474			const issue = await Promise.allSettled([
475				target.issue({ action: "message", clientOperationId: "after", text: "continued" }),
476			]);
477			expect.soft(issue[0]?.status, "D110C_0C1F5B0U_RECOVERY_BEFORE_CLEANUP_FAILED").toBe("fulfilled");
478			observation.closeFault = true;
479			await expect(target.close()).rejects.toThrow();
480			await expect(
481				target.issue({ action: "message", clientOperationId: "after-close", text: "forbidden" })
482			).rejects.toThrow();
483			expect(observation.activate.filter((plane) => plane.currentEphemeralAuthority() !== undefined)).toHaveLength(0);
484		});
485		it.each([false, true])(
486			"rebinds creator-close to the fresh real plane or fails terminally (rebind failure %s)",
487			async (failRebind) => {
488				observation.fault = "partial-unknown";
489				observation.failRebind = failRebind;
490				const { target } = await openRebasePair(2, 33_000, true);
491				const publicIssue = target.issue({ action: "message", clientOperationId: "after", text: "continued" });
492				if (failRebind) {
493					await expect(publicIssue, "D110C_0C1F5B0U_REBIND_TERMINAL_CODE_MISSING").rejects.toThrow(
494						"D110C_B_CLOSE_REBIND_FAILED"
495					);
496					await expect(target.sealEpoch()).rejects.toThrow("D110C_B_CLOSE_REBIND_FAILED");
497				} else {
498					await expect(publicIssue, "D110C_0C1F5B0U_BOUND_RECOVERY_NOT_COMPLETED").resolves.toBeUndefined();
499					expect(observation.bound).toHaveLength(2);
500					expect(observation.bound[1]?.plane).toBe(observation.activate[1]);
501					expect(observation.bound[0]?.plane.currentEphemeralAuthority()).toBeUndefined();
502					// This prerequisite proves receiver custody, not the parent f5b checkpoint producer.
503					await Promise.allSettled([target.sealEpoch(), target.adoptCreatorSuccessor()]);
504					expect(observation.bound.at(-1)?.plane).toBe(observation.activate.at(-1));
505				}
506			}
507		);
508	});
